%[text] %[text:anchor:H_90909E03] ## Imposition of weak Dirichlet boundary conditions using the Lagrange Multipliers method
Lambda = ...
    utilityFunctionsWeakDBCTimoshenkoBeam.computeLagrangeMultipliersMtxWeakDirichletBoundaryConditions ...
    (msh, homDOFs, computeBasisFunctionsAndDerivsU);
%[text] %[text:anchor:H_E6FB26C7] ### Computation of the stiffness matrix accounting for the Lagrange Multipliers contributions and solution of the linear equation system
numDOFsLM = numel(homDOFs);
stiffMtxLM = [K                 Lambda
              transpose(Lambda) zeros(numDOFsLM)];
loadVctLM = [F
              zeros(numDOFsLM, 1)];
uLM = stiffMtxLM\loadVctLM;
%[text] %[text:anchor:H_DB5ADB20] ### Visualization of the deformed configuration
plot_postprocConfigurationTimoshenkoBeam ... %[output:39345451]
    (msh, uLM, "displacement", choiceShapeFunctionsPrimal); %[output:39345451]
hold on; %[output:39345451]
fplot(wEx, [X0 XL], '-k', LineWidth=2); %[output:39345451]
hold off; %[output:39345451]
grid on; %[output:39345451]
if choiceShapeFunctionsPrimal == 1
    str = "1";
else
    str = "2";
end
legend("L" + str, "analytical", Location="best") %[output:39345451]
title("Deformation using the Lagrange Multipliers method") %[output:39345451]
%[text] %[text:anchor:H_B3B272C9] ### Visualization of the cross-sectional rotation field
plot_postprocConfigurationTimoshenkoBeam ... %[output:63ebddbb]
    (msh, uLM, "rotation", choiceShapeFunctionsPrimal); %[output:63ebddbb]
hold on; %[output:63ebddbb]
fplot(betaEx, [X0 XL], '-k', LineWidth=2); %[output:63ebddbb]
hold off; %[output:63ebddbb]
grid on; %[output:63ebddbb]
if choiceShapeFunctionsPrimal == 1
    str = "1";
else
    str = "2";
end
legend("L" + str, "analytical", Location="best") %[output:63ebddbb]
title("Cross-sectional rotation $\beta$ using " + ... %[output:group:338b504a] %[output:63ebddbb]
    "the Lagrange Multipliers method", Interpreter="latex") %[output:group:338b504a] %[output:63ebddbb]
%[text] %[text:anchor:H_80D0CAC2] ### Computation of the error on the Dirichlet boundary
disp("Error in the vertical deflection at the Dirichlet " + ... %[output:group:4da07ed4] %[output:1634d8a8]
    "boundary (Lagrange Multipliers): " + sum(abs(uLM(homDOFs)))); %[output:group:4da07ed4] %[output:1634d8a8]
%[text] %[text:anchor:H_81891232] ### Computation of the error in the $L^2(0,L)$-norm
numGP = 4;
[errL2LMU, errL2LMBeta] = computeL2ErrorTimoshenkoBeam ...
    (msh, uLM(1:numDOFs), computeBasisFunctionsAndDerivsU, ...
    wEx, betaEx, numGP);
disp("Error in the L2-norm for the vertical deflection " + ... %[output:group:0c46fdff] %[output:8fad38e0]
    "in the domain (Lagrange Multipliers): " + errL2LMU); %[output:group:0c46fdff] %[output:8fad38e0]
disp("Error in the L2-norm for the cross-sectional rotation " + ... %[output:group:7c382635] %[output:24139b5f]
    "in the domain (Lagrange Multipliers): " + errL2LMBeta); %[output:group:7c382635] %[output:24139b5f]
